//! Frame-wise feature references (fixture `features.json`, generated by
//! `cases/features.py`): spectral centroid / bandwidth / rolloff / flatness /
//! contrast, poly_features, rms, zero_crossing_rate, pcen, frequency weightings,
//! perceptual_weighting and the reassigned spectrogram.
//!
//! Tolerances are peak-relative (`|a - e| <= rtol * max|e|`, see
//! `common::assert_close`), per output row where rows have different scales
//! (contrast bands, polynomial coefficients). The reference computes the same
//! operations in the same order, so the remaining differences are the STFT's FFT
//! round-off (a different FFT implementation, ~1e-16 of the peak per bin),
//! summation order (pairwise or BLAS sums in the reference, sequential sums here)
//! and libm ulps. Each tolerance says what else
//! applies. Measured errors are printed with `--nocapture`.

use std::num::NonZeroUsize;

use audio_samples::operations::features::{
    AudioFeatures, FrequencyWeighting, PcenConfig, PolyFeaturesConfig, ReassignRefPower,
    ReassignedSpectrogramConfig, RmsConfig, SpectralBandwidthConfig, SpectralCentroidConfig,
    SpectralContrastConfig, SpectralFlatnessConfig, SpectralRolloffConfig, ZeroCrossingRateConfig,
    ZeroCrossingReference, frequency_weighting, multi_frequency_weighting, pcen,
    perceptual_weighting, rms_from_spectrogram, spectral_bandwidth_from_spectrogram,
    spectral_centroid_from_spectrogram,
};
use audio_samples::operations::spectrum::{
    AudioSpectrum, DbConfig, DbReference, MelSpectrogramConfig, StftConfig, StftPadMode,
};
use audio_samples::{AudioSamples, Window, nzu};
use ndarray::{Array2, Array3, Axis, s};
use serde_json::Value;

use crate::common::{arr2, arr3, assert_close, errors, f64s, load, mono, signal, sr, stereo};

/// See the comment in `spectral_defaults` (dB of the smallest band magnitudes).
const CONTRAST_DB_TOL: f64 = 5e-10;

fn fixture() -> &'static Value {
    static F: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    F.get_or_init(|| load("features"))
}

fn nz(n: usize) -> NonZeroUsize {
    NonZeroUsize::new(n).expect("non-zero")
}

fn step(v: &Value) -> usize {
    v.as_u64().expect("integer") as usize
}

/// Assert and print the measured agreement.
#[track_caller]
fn check<'a>(
    what: &str,
    actual: impl IntoIterator<Item = &'a f64> + Clone,
    expected: impl IntoIterator<Item = &'a f64> + Clone,
    rtol: f64,
) {
    let (abs, rel) = errors(actual.clone(), expected.clone());
    eprintln!("{what:<52} max abs {abs:.3e}  peak-rel {rel:.3e}  (rtol {rtol:e})");
    assert_close(what, actual, expected, rtol, 0.0);
}

/// Compare a `(channels, rows, frames)` result with a reference array: 2-D
/// `(rows, frames)` for mono input, 3-D for multichannel. Each row is checked
/// against its own peak.
#[track_caller]
fn check_rows(what: &str, actual: &Array3<f64>, expected: &Value, rtol: f64) {
    let exp: Array3<f64> = if expected[0][0].is_array() {
        arr3(expected)
    } else {
        arr2(expected).insert_axis(Axis(0))
    };
    assert_eq!(actual.shape(), exp.shape(), "{what}: shape");
    for c in 0..exp.dim().0 {
        for r in 0..exp.dim().1 {
            let a = actual.slice(s![c, r, ..]).to_vec();
            let e = exp.slice(s![c, r, ..]).to_vec();
            check(&format!("{what} [ch {c}, row {r}]"), &a, &e, rtol);
        }
    }
}

fn audio(name: &str) -> AudioSamples<'static, f64> {
    if name == "stereo" {
        stereo()
    } else {
        mono(name)
    }
}

fn fft_freqs(n_fft: usize) -> Vec<f64> {
    // Bin frequencies k / (n_fft * (1 / sr)), evaluated in the reference's order
    // so they round the same way.
    let val = 1.0 / (n_fft as f64 * (1.0 / f64::from(sr())));
    (0..=n_fft / 2).map(|k| k as f64 * val).collect()
}

#[test]
fn spectral_defaults() {
    for (name, case) in fixture()["spectral"].as_object().unwrap() {
        let x = audio(name);
        // Ratios / sums of STFT magnitudes: FFT round-off plus summation order.
        let tol = 1e-12;
        check_rows(
            &format!("{name} centroid"),
            &x.spectral_centroid_frames(&SpectralCentroidConfig::librosa())
                .unwrap(),
            &case["centroid"],
            tol,
        );
        check_rows(
            &format!("{name} bandwidth"),
            &x.spectral_bandwidth_frames(&SpectralBandwidthConfig::librosa())
                .unwrap(),
            &case["bandwidth"],
            tol,
        );
        // Rolloff picks a bin: it is exact unless the cumulative sum lands within
        // round-off of the threshold (it does not for these signals).
        check_rows(
            &format!("{name} rolloff"),
            &x.spectral_rolloff_frames(&SpectralRolloffConfig::librosa())
                .unwrap(),
            &case["rolloff"],
            0.0,
        );
        // exp(mean(log P)) / mean(P): log/exp ulps on top of the STFT round-off,
        // amplified in nearly-silent edge frames whose bins sit at amin.
        check_rows(
            &format!("{name} flatness"),
            &x.spectral_flatness_frames(&SpectralFlatnessConfig::librosa())
                .unwrap(),
            &case["flatness"],
            1e-11,
        );
        // dB differences of quantile means. The band selection and the sort are
        // exact, but with quantile 0.02 the valley is the mean of the 1-3 smallest
        // magnitudes in a band, which can be ~1e-5 of the frame peak: their relative
        // FFT round-off is eps * peak / valley ~ 1e-11, and 10 log10 turns it into
        // an absolute dB error of 4.3x that (measured <= 5e-11 of the row peak; the
        // linear contrast below agrees to 7e-14).
        check_rows(
            &format!("{name} contrast"),
            &x.spectral_contrast_frames(&SpectralContrastConfig::librosa())
                .unwrap(),
            &case["contrast"],
            CONTRAST_DB_TOL,
        );
        // Least squares: the reference uses an SVD (LAPACK gelsd), this crate
        // Householder QR on the same column-scaled Vandermonde matrix; both are
        // backward stable, so the solutions agree to cond(A) * eps (cond ~ 3
        // for order 1).
        check_rows(
            &format!("{name} poly1"),
            &x.poly_features(&PolyFeaturesConfig::librosa()).unwrap(),
            &case["poly1"],
            1e-11,
        );
        // Mean of squares, sqrt: summation order only.
        check_rows(
            &format!("{name} rms"),
            &x.rms_frames(&RmsConfig::librosa()).unwrap(),
            &case["rms"],
            1e-13,
        );
        // Integer crossing counts / frame_length: exact.
        check_rows(
            &format!("{name} zcr"),
            &x.zero_crossing_rate_frames(&ZeroCrossingRateConfig::librosa())
                .unwrap(),
            &case["zcr"],
            0.0,
        );
    }
}

#[test]
fn spectral_nondefault_parameters() {
    for (name, case) in fixture()["nondefault"].as_object().unwrap() {
        let x = mono(name);
        let nc = StftConfig::librosa()
            .with_n_fft(nzu!(1024))
            .with_hop_length(Some(nzu!(256)))
            .with_center(false);
        let tol = 1e-12;
        check_rows(
            &format!("{name} centroid_nocenter"),
            &x.spectral_centroid_frames(&SpectralCentroidConfig::librosa().with_stft(nc.clone()))
                .unwrap(),
            &case["centroid_nocenter"],
            tol,
        );
        let hr = StftConfig::librosa()
            .with_window(Window::Hamming)
            .with_pad_mode(StftPadMode::Reflect);
        check_rows(
            &format!("{name} centroid_hamming_reflect"),
            &x.spectral_centroid_frames(&SpectralCentroidConfig::librosa().with_stft(hr))
                .unwrap(),
            &case["centroid_hamming_reflect"],
            tol,
        );
        check_rows(
            &format!("{name} bandwidth_p1"),
            &x.spectral_bandwidth_frames(&SpectralBandwidthConfig::librosa().with_p(1.0))
                .unwrap(),
            &case["bandwidth_p1"],
            tol,
        );
        // p = 3 goes through pow(x, 3) and pow(x, 1/3): libm ulps.
        check_rows(
            &format!("{name} bandwidth_p3_nonorm"),
            &x.spectral_bandwidth_frames(
                &SpectralBandwidthConfig::librosa()
                    .with_p(3.0)
                    .with_norm(false),
            )
            .unwrap(),
            &case["bandwidth_p3_nonorm"],
            tol,
        );
        // S= path with an explicit centroid.
        let c1024 = StftConfig::librosa()
            .with_n_fft(nzu!(1024))
            .with_hop_length(Some(nzu!(256)));
        let s1024 = x.spectrogram_matrix(&c1024, 1.0).unwrap();
        let f1024 = fft_freqs(1024);
        let cen = spectral_centroid_from_spectrogram(s1024.view(), &f1024).unwrap();
        check_rows(
            &format!("{name} bandwidth_S_centroid"),
            &spectral_bandwidth_from_spectrogram(
                s1024.view(),
                &f1024,
                Some(cen.view()),
                &SpectralBandwidthConfig::librosa(),
            )
            .unwrap(),
            &case["bandwidth_S_centroid"],
            tol,
        );
        // Bin selection: exact.
        check_rows(
            &format!("{name} rolloff_050"),
            &x.spectral_rolloff_frames(&SpectralRolloffConfig::librosa().with_roll_percent(0.5))
                .unwrap(),
            &case["rolloff_050"],
            0.0,
        );
        check_rows(
            &format!("{name} rolloff_099_nocenter"),
            &x.spectral_rolloff_frames(
                &SpectralRolloffConfig::librosa()
                    .with_roll_percent(0.99)
                    .with_stft(nc.clone()),
            )
            .unwrap(),
            &case["rolloff_099_nocenter"],
            0.0,
        );
        // As the default flatness case.
        check_rows(
            &format!("{name} flatness_power1"),
            &x.spectral_flatness_frames(&SpectralFlatnessConfig::librosa().with_power(1.0))
                .unwrap(),
            &case["flatness_power1"],
            1e-11,
        );
        check_rows(
            &format!("{name} flatness_amin"),
            &x.spectral_flatness_frames(&SpectralFlatnessConfig::librosa().with_amin(1e-4))
                .unwrap(),
            &case["flatness_amin"],
            1e-11,
        );
        // Linear contrast: no logarithm, so only the means' round-off.
        check_rows(
            &format!("{name} contrast_linear"),
            &x.spectral_contrast_frames(&SpectralContrastConfig::librosa().with_linear(true))
                .unwrap(),
            &case["contrast_linear"],
            1e-12,
        );
        // dB contrast: as the default case.
        check_rows(
            &format!("{name} contrast_b4_f300_q01"),
            &x.spectral_contrast_frames(
                &SpectralContrastConfig::librosa()
                    .with_n_bands(nzu!(4))
                    .with_fmin(300.0)
                    .with_quantile(0.1),
            )
            .unwrap(),
            &case["contrast_b4_f300_q01"],
            CONTRAST_DB_TOL,
        );
        check_rows(
            &format!("{name} contrast_nfft1024"),
            &x.spectral_contrast_frames(
                &SpectralContrastConfig::librosa().with_stft(c1024.clone()),
            )
            .unwrap(),
            &case["contrast_nfft1024"],
            CONTRAST_DB_TOL,
        );
        // As poly1; order 2 has cond(A) ~ 20 after column scaling.
        check_rows(
            &format!("{name} poly0"),
            &x.poly_features(&PolyFeaturesConfig::librosa().with_order(0))
                .unwrap(),
            &case["poly0"],
            1e-11,
        );
        check_rows(
            &format!("{name} poly2"),
            &x.poly_features(&PolyFeaturesConfig::librosa().with_order(2))
                .unwrap(),
            &case["poly2"],
            1e-11,
        );
        // Summation order only.
        check_rows(
            &format!("{name} rms_nocenter"),
            &x.rms_frames(
                &RmsConfig::librosa()
                    .with_frame_length(nzu!(1024))
                    .with_hop_length(nzu!(256))
                    .with_center(false),
            )
            .unwrap(),
            &case["rms_nocenter"],
            1e-13,
        );
        check_rows(
            &format!("{name} rms_reflect_odd"),
            &x.rms_frames(
                &RmsConfig::librosa()
                    .with_frame_length(nzu!(1001))
                    .with_hop_length(nzu!(300))
                    .with_pad_mode(StftPadMode::Reflect),
            )
            .unwrap(),
            &case["rms_reflect_odd"],
            1e-13,
        );
        // Parseval sum over STFT magnitudes: FFT round-off.
        let sd = x.spectrogram_matrix(&StftConfig::librosa(), 1.0).unwrap();
        check_rows(
            &format!("{name} rms_S"),
            &rms_from_spectrogram(sd.view(), nzu!(2048)).unwrap(),
            &case["rms_S"],
            1e-12,
        );
        // Exact counts.
        check_rows(
            &format!("{name} zcr_nocenter"),
            &x.zero_crossing_rate_frames(
                &ZeroCrossingRateConfig::librosa()
                    .with_frame_length(nzu!(1024))
                    .with_hop_length(nzu!(256))
                    .with_center(false),
            )
            .unwrap(),
            &case["zcr_nocenter"],
            0.0,
        );
        check_rows(
            &format!("{name} zcr_thresh_max"),
            &x.zero_crossing_rate_frames(
                &ZeroCrossingRateConfig::librosa()
                    .with_threshold(0.05)
                    .with_ref_magnitude(ZeroCrossingReference::Max),
            )
            .unwrap(),
            &case["zcr_thresh_max"],
            0.0,
        );
        check_rows(
            &format!("{name} zcr_zero_neg_pad"),
            &x.zero_crossing_rate_frames(
                &ZeroCrossingRateConfig::librosa()
                    .with_threshold(0.01)
                    .with_zero_pos(false)
                    .with_pad(true),
            )
            .unwrap(),
            &case["zcr_zero_neg_pad"],
            0.0,
        );
    }
}

#[test]
fn pcen_cases() {
    let f = &fixture()["pcen"];
    let rs = step(&f["row_step"]);
    let rate = f64::from(sr());
    let scale = 2f64.powi(31);
    let mel = mono("mix")
        .melspectrogram(&MelSpectrogramConfig::librosa())
        .unwrap()
        * scale;
    let sub = |a: Array3<f64>| a.slice(s![.., ..;rs, ..]).to_owned();
    // The IIR recursion is the same direct-form II transposed update as the
    // reference, with the same steady-state initial condition; the remaining error is
    // the mel input's (FFT + matrix product) round-off and log/exp ulps.
    let tol = 1e-12;
    let cases: [(&str, PcenConfig); 5] = [
        ("default", PcenConfig::librosa()),
        ("max_size3", PcenConfig::librosa().with_max_size(nzu!(3))),
        ("power0", PcenConfig::librosa().with_power(0.0)),
        ("bias0", PcenConfig::librosa().with_bias(0.0).with_gain(0.8)),
        (
            "b_explicit_hop256",
            PcenConfig::librosa()
                .with_hop_length(nzu!(256))
                .with_b(Some(0.2))
                .with_time_constant(0.1),
        ),
    ];
    for (name, cfg) in cases {
        check_rows(
            &format!("pcen {name}"),
            &sub(pcen(mel.view(), rate, &cfg).unwrap()),
            &f[name],
            tol,
        );
    }
    let mel_st = stereo()
        .melspectrogram(&MelSpectrogramConfig::librosa())
        .unwrap()
        * scale;
    check_rows(
        "pcen stereo",
        &sub(pcen(mel_st.view(), rate, &PcenConfig::librosa()).unwrap()),
        &f["stereo"],
        tol,
    );
    let ms = step(&f["stft_notes_mag_step"]);
    let mag = mono("notes")
        .spectrogram_matrix(&StftConfig::librosa(), 1.0)
        .unwrap()
        * scale;
    let p = pcen(mag.view(), rate, &PcenConfig::librosa()).unwrap();
    check_rows(
        "pcen stft notes",
        &p.slice(s![.., ..;ms, ..]).to_owned(),
        &f["stft_notes"],
        tol,
    );
}

fn kind(c: char) -> FrequencyWeighting {
    match c {
        'A' => FrequencyWeighting::A,
        'B' => FrequencyWeighting::B,
        'C' => FrequencyWeighting::C,
        'D' => FrequencyWeighting::D,
        'Z' => FrequencyWeighting::Z,
        other => panic!("weighting {other}"),
    }
}

#[test]
fn frequency_weightings() {
    let f = &fixture()["weighting"];
    let freqs = f64s(&f["freqs"]);
    let special = f64s(&f["special"]);
    // Same expression evaluated in the same order; log10 ulps on values of order
    // 1-100 dB.
    let tol = 1e-14;
    for k in ['A', 'B', 'C', 'D'] {
        check(
            &format!("{k}_weighting fft freqs"),
            &frequency_weighting(&freqs, kind(k), Some(-80.0)),
            &f64s(&f[k.to_string().as_str()]),
            tol,
        );
        check(
            &format!("{k}_weighting special, min_db None"),
            &frequency_weighting(&special[1..], kind(k), None),
            &f64s(&f[format!("{k}_special_nomin").as_str()]),
            tol,
        );
        check(
            &format!("{k}_weighting special, min_db -40"),
            &frequency_weighting(&special, kind(k), Some(-40.0)),
            &f64s(&f[format!("{k}_special_min40").as_str()]),
            tol,
        );
    }
    let zac: Vec<FrequencyWeighting> = "ZAC".chars().map(kind).collect();
    check(
        "multi_frequency_weighting ZAC",
        &multi_frequency_weighting(&freqs, &zac, Some(-80.0)),
        &arr2(&f["multi_ZAC"]),
        tol,
    );
    let dba: Vec<FrequencyWeighting> = "DBA".chars().map(kind).collect();
    check(
        "multi_frequency_weighting DBA min -60",
        &multi_frequency_weighting(&freqs, &dba, Some(-60.0)),
        &arr2(&f["multi_DBA_min60"]),
        tol,
    );
}

#[test]
fn perceptual_weighting_cases() {
    let f = &fixture()["weighting"]["perceptual"];
    let bs = step(&f["bin_step"]);
    let freqs = fft_freqs(2048);
    let p = mono("mix")
        .spectrogram_matrix(&StftConfig::librosa(), 2.0)
        .unwrap();
    let pst = stereo()
        .spectrogram_matrix(&StftConfig::librosa(), 2.0)
        .unwrap();
    let sub = |a: Array3<f64>| a.slice(s![.., ..;bs, ..]).to_owned();
    // dB of FFT power: the absolute error of 10 log10(P) is ~4.3 * relative error of
    // P, which is large in near-empty bins (relative to their own value); bounded
    // peak-relatively by the dB range (-100 .. 40 dB here). Without the top_db
    // floor (D_no_top_db) bins near amin are kept: measured 6.5e-12; others ~1e-14.
    let tol = 1e-10;
    let cases = [
        (
            "A_default",
            FrequencyWeighting::A,
            DbConfig::librosa_power(),
            &p,
        ),
        (
            "C_ref_max",
            FrequencyWeighting::C,
            DbConfig::librosa_power().with_reference(DbReference::Max),
            &p,
        ),
        (
            "D_no_top_db",
            FrequencyWeighting::D,
            DbConfig::librosa_power().with_top_db(None),
            &p,
        ),
        (
            "A_stereo",
            FrequencyWeighting::A,
            DbConfig::librosa_power(),
            &pst,
        ),
    ];
    for (name, k, db, spec) in cases {
        let w = perceptual_weighting(spec.view(), &freqs, k, &db).unwrap();
        let expected = &f[name];
        let exp: Array3<f64> = if expected[0][0].is_array() {
            arr3(expected)
        } else {
            arr2(expected).insert_axis(Axis(0))
        };
        check(&format!("perceptual_weighting {name}"), &sub(w), &exp, tol);
    }
}

fn bools2(v: &Value) -> Array2<bool> {
    let rows: Vec<Vec<bool>> = v
        .as_array()
        .unwrap()
        .iter()
        .map(|r| {
            r.as_array()
                .unwrap()
                .iter()
                .map(|b| b.as_bool().unwrap())
                .collect()
        })
        .collect();
    let (r, c) = (rows.len(), rows[0].len());
    Array2::from_shape_vec((r, c), rows.into_iter().flatten().collect()).unwrap()
}

#[test]
fn reassigned_spectrogram_cases() {
    let f = &fixture()["reassigned"];
    let (bs, fs) = (step(&f["bin_step"]), step(&f["frame_step"]));
    for (name, case) in f.as_object().unwrap() {
        if !case.is_object() {
            continue;
        }
        let p = &case["params"];
        let mut stft = StftConfig::librosa();
        if let Some(v) = p.get("n_fft") {
            stft.n_fft = nz(step(v));
        }
        if let Some(v) = p.get("hop_length") {
            stft.hop_length = Some(nz(step(v)));
        }
        if let Some(v) = p.get("win_length") {
            stft.win_length = Some(nz(step(v)));
        }
        if let Some(v) = p.get("center") {
            stft.center = v.as_bool().unwrap();
        }
        if p.get("window").is_some() {
            stft.window = Window::Hamming;
        }
        let mut cfg = ReassignedSpectrogramConfig::librosa().with_stft(stft);
        if let Some(v) = p.get("fill_nan") {
            cfg.fill_nan = v.as_bool().unwrap();
        }
        if let Some(v) = p.get("clip") {
            cfg.clip = v.as_bool().unwrap();
        }
        if let Some(v) = p.get("reassign_times") {
            cfg.reassign_times = v.as_bool().unwrap();
        }
        if let Some(v) = p.get("reassign_frequencies") {
            cfg.reassign_frequencies = v.as_bool().unwrap();
        }
        if let Some(v) = p.get("ref_power") {
            cfg.ref_power = match v {
                Value::String(_) => ReassignRefPower::Max,
                v => ReassignRefPower::Value(v.as_f64().unwrap()),
            };
        }
        let signal = if name.contains("fill_nan") || name.starts_with("freq_only") {
            "notes"
        } else {
            "mix"
        };
        let r = mono(signal).reassigned_spectrogram(&cfg).unwrap();
        let shape: Vec<usize> = case["shape"].as_array().unwrap().iter().map(step).collect();
        assert_eq!(&r.mags.shape()[1..], &shape[..], "{name}: shape");
        let pick = |a: &Array3<f64>| a.slice(s![0, ..;bs, ..;fs]).to_owned();
        // Magnitudes: FFT round-off.
        check(
            &format!("reassigned {name} mags"),
            &pick(&r.mags),
            &arr2(&case["mags"]),
            1e-13,
        );
        for (what, ours) in [("freqs", pick(&r.freqs)), ("times", pick(&r.times))] {
            let mask = bools2(&case[format!("{what}_nan").as_str()]);
            let ours_mask = ours.mapv(f64::is_nan);
            // The NaN pattern comes from the |S| < sqrt(ref_power) threshold; it
            // matches unless a magnitude is within round-off of the threshold.
            assert_eq!(ours_mask, mask, "reassigned {name} {what}: NaN pattern");
            let ours0 = ours.mapv(|v| if v.is_nan() { 0.0 } else { v });
            // Corrections are ratios S_dh / S_h (S_th / S_h): their round-off grows
            // as |S_h| approaches the threshold (1e-3 = sqrt(1e-6) by default, vs a
            // peak of ~200), i.e. by up to ~1e5 over the FFT's 1e-16. Bounded
            // peak-relatively (peaks: sr/2 Hz, 1 s); measured <= 6e-13.
            check(
                &format!("reassigned {name} {what}"),
                &ours0,
                &arr2(&case[what]),
                1e-11,
            );
        }
    }
}

/// A shared test signal as mono `f32` audio (exact: the signals are 16-bit PCM).
fn mono_f32(name: &str) -> AudioSamples<'static, f32> {
    let x: Vec<f32> = signal(name).iter().map(|&v| v as f32).collect();
    let rate = std::num::NonZeroU32::new(sr()).expect("sr > 0");
    AudioSamples::new_mono(ndarray::Array1::from(x), rate).expect("valid mono audio")
}

/// Compare `(channels, rows, frames)` arrays row by row (each row against its
/// own peak).
#[track_caller]
fn check_rows_arr(what: &str, actual: &Array3<f64>, expected: &Array3<f64>, rtol: f64) {
    assert_eq!(actual.shape(), expected.shape(), "{what}: shape");
    for c in 0..expected.dim().0 {
        for r in 0..expected.dim().1 {
            let a = actual.slice(s![c, r, ..]).to_vec();
            let e = expected.slice(s![c, r, ..]).to_vec();
            check(&format!("{what} [ch {c}, row {r}]"), &a, &e, rtol);
        }
    }
}

/// `f32` audio against the reference run on the same samples cast to `float32`,
/// and against this crate's `f64` path.
///
/// The reference's float32 STFT multiplies the frames by a float64 window, so it
/// computes the FFT in float64 and rounds the result to complex64: its output is
/// the float64 result rounded once. Here the whole computation runs in `f32`, so
/// both comparisons measure the `f32` round-off of this crate (the two measured
/// errors agree to within 2e-7 of each other).
///
/// Tolerances (peak-relative per row; f32 epsilon 1.19e-7):
/// - centroid, bandwidth: FFT round-off grows as log2(2048) = 11 eps, plus the
///   sums over 1025 bins; measured <= 1.9e-6, bound 4e-6 (34 eps).
/// - flatness: log / exp of the power on top; measured <= 2.6e-6, bound 5e-6.
/// - rms: a sequential sum of 2048 squares (the reference uses a pairwise float32
///   sum); measured <= 1.3e-6, bound 4e-6.
/// - contrast (dB): the valley is the mean of the 1-3 smallest magnitudes of a
///   band. For noise they are within a few orders of magnitude of the band
///   peak (measured 3.9e-6, bound 1e-5). For the tonal `mix` signal they lie far
///   below the peak, where the f32 FFT's absolute round-off (about 11 eps of the
///   frame peak) is a large relative error of the valley: measured up to
///   0.22 dB (9.2e-3 of the row peak), bound 2e-2. The linear quantities are
///   checked tightly above.
/// - zcr: crossing counts of the same samples; exact.
#[test]
fn float32_input() {
    let f = &fixture()["float32"];
    for (name, case) in f.as_object().unwrap() {
        let x = mono_f32(name);
        let x64 = mono(name);
        let contrast_tol = if name == "mix" { 2e-2 } else { 1e-5 };
        let cases: [(&str, Array3<f32>, Array3<f64>, f64); 6] = [
            (
                "centroid",
                x.spectral_centroid_frames(&SpectralCentroidConfig::librosa())
                    .unwrap(),
                x64.spectral_centroid_frames(&SpectralCentroidConfig::librosa())
                    .unwrap(),
                4e-6,
            ),
            (
                "bandwidth",
                x.spectral_bandwidth_frames(&SpectralBandwidthConfig::librosa())
                    .unwrap(),
                x64.spectral_bandwidth_frames(&SpectralBandwidthConfig::librosa())
                    .unwrap(),
                4e-6,
            ),
            (
                "flatness",
                x.spectral_flatness_frames(&SpectralFlatnessConfig::librosa())
                    .unwrap(),
                x64.spectral_flatness_frames(&SpectralFlatnessConfig::librosa())
                    .unwrap(),
                5e-6,
            ),
            (
                "contrast",
                x.spectral_contrast_frames(&SpectralContrastConfig::librosa())
                    .unwrap(),
                x64.spectral_contrast_frames(&SpectralContrastConfig::librosa())
                    .unwrap(),
                contrast_tol,
            ),
            (
                "rms",
                x.rms_frames(&RmsConfig::librosa()).unwrap(),
                x64.rms_frames(&RmsConfig::librosa()).unwrap(),
                4e-6,
            ),
            (
                "zcr",
                x.zero_crossing_rate_frames(&ZeroCrossingRateConfig::librosa())
                    .unwrap(),
                x64.zero_crossing_rate_frames(&ZeroCrossingRateConfig::librosa())
                    .unwrap(),
                0.0,
            ),
        ];
        for (what, ours, ours64, tol) in cases {
            let ours = ours.mapv(f64::from);
            check_rows(
                &format!("f32 {name} {what} vs reference float32"),
                &ours,
                &case[what],
                tol,
            );
            check_rows_arr(&format!("f32 {name} {what} vs f64"), &ours, &ours64, tol);
        }
    }
}
